import {websiteShowcase,WEBSITE_DRAFT,WEBSITE_REPORT,WEBSITE_PACKAGES} from './website-offer.js';
import {CONSULTING} from './offer-catalog.js';
import {CONSULTATION_TYPES as TYPES,COMMON_BRIEF_FIELDS as COMMON,BRIEF_REQUIRED as REQUIRED,CONSULTATION_STATES as STATES,CONSULTATION_ACTIONS as ACTIONS,REPORT_FIELDS as REPORT} from './consultation-schema.js';

export function consultationText(value,esc){return String(value||'').split(/(https:\/\/[^\s<>]+)/g).map(part=>{if(!part.startsWith('https://'))return esc(part);const candidate=part.replace(/[.,;)]+$/,'');try{const url=new URL(candidate);if(url.protocol!=='https:'||url.username||url.password)return esc(part);return `<a href="${esc(url.href)}" target="_blank" rel="noopener noreferrer">${esc(candidate)}</a>${esc(part.slice(candidate.length))}`;}catch{return esc(part);}}).join('');}

export function createConsultationUI({api,esc,getState,getBoot,openDialog,closeDialog,toast,uploadFile}){
  let websites=false,active=false,admin=false,org='',data=null,sequence=0,pending=false,filter='all',clientFilter='all',extraAssets=[];
  const date=v=>v?new Date(v).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}):'—';
  const money=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(v/100);
  const endpoint=()=>admin?'/api/portal/consultations-admin':'/api/portal/'+org+'/consultations';
  const requests=()=>(data?.requests||[]).filter(r=>!websites||r.type==='website');
  const reportFields=r=>r?.type==='website'?WEBSITE_REPORT:REPORT;
  const name=r=>data?.clients.find(c=>c.id===r.orgId)?.name||getState()?.company.name||'';
  const btn=(title,action,id='',primary=false)=>`<button type="button" class="p-button ${primary?'primary':'secondary'}" data-consult="${action}" data-id="${esc(id)}">${esc(title)}</button>`;
  const area=(key,title,value='',required=false)=>`<label class="p-field"><span>${esc(title)}${required?' *':''}</span><textarea name="${key}" rows="3" maxlength="${REPORT.some(([k])=>k===key)?12000:['scope','deliverables'].includes(key)?8000:4000}" ${required?'required':''}>${esc(value)}</textarea></label>`;
  const input=(key,title,value='',type='text',more='')=>`<label class="p-field"><span>${esc(title)}</span><input name="${key}" type="${type}" value="${esc(value)}" required ${more}></label>`;
  const check=(key,title)=>`<label class="assisted-check"><input name="${key}" type="checkbox" required><span>${esc(title)}</span></label>`;
  const error='<p class="form-error" role="alert" hidden></p>';
  const form=(act,r,body,title='Confirmar')=>`<form class="consult-form" data-consult-form="${act}" data-id="${esc(r?.id||'')}" data-org="${esc(r?.orgId||org)}" data-version="${r?.version||0}" data-key="${crypto.randomUUID()}">${body}${error}<button class="p-button primary">${title}</button></form>`;
  const links=assets=>`<ul class="consult-files">${(assets||[]).map(a=>`<li><a href="/api/portal/files/${encodeURIComponent(a.id)}" target="_blank" rel="noopener">${esc(a.name)}</a></li>`).join('')}</ul>`;
  const files=()=>[...new Map([...(getState()?.assets||[]),...extraAssets].map(a=>[a.id,a])).values()];
  const chooser=(assets,selected=[])=>`<fieldset class="consult-files"><legend>Arquivos deste pedido (opcional)</legend><div data-consult-assets>${assets.map(a=>`<label class="assisted-check"><input type="checkbox" name="assetIds" value="${esc(a.id)}" ${selected.some(s=>s.id===a.id)?'checked':''}><span>${esc(a.name)}</span></label>`).join('')}</div></fieldset>`;
  const upload=(delivery=false)=>`<label class="p-field"><span>${delivery?'Anexar material de entrega · até 3 MB por arquivo':'Enviar arquivo · até 25 MB por arquivo'}</span><input type="file" data-consult-upload="${delivery?'delivery':'brief'}" accept="image/png,image/jpeg,image/webp,video/mp4,audio/*,application/pdf"></label><p class="micro-copy">PDF, imagens, áudio ou MP4. Links podem ser informados nos campos de texto. Não envie senhas ou dados pessoais de clientes e pacientes.</p>`;
  function next(r){return {draft:'Complete e envie o formulário.',triage:'Equipe: analisar briefing e preparar proposta.',needs_info:'Cliente: responder às informações solicitadas.',proposed:'Cliente: conferir e aceitar ou pedir ajuste.',accepted:!r.payment?'Equipe: conferir pagamento combinado na proposta.':!r.briefVerified?'Equipe: conferir briefing completo.':'Equipe: iniciar trabalho e prazo.',working:'Equipe: preparar a entrega.',paused:'Cliente: enviar o complemento; equipe: retomar o prazo.',delivered:'Cliente: revisar a entrega e aceitar ou consolidar ajustes.',revision:'Equipe: preparar a revisão solicitada.',completed:'Entrega aceita pelo cliente.',canceled:'Solicitação encerrada antes da contratação.'}[r.state];}
  function paint(){const host=document.querySelector('#consult-workspace');if(!active||!host)return;if(!data){host.innerHTML='<p>Carregando consultorias…</p>';return;}
    const filtered=requests().filter(r=>(filter==='all'||r.state===filter)&&(clientFilter==='all'||r.orgId===clientFilter));
    host.innerHTML=`${admin?`<aside class="consult-notice" role="status">${data.pendingCount} solicitação(ões) aguardando triagem ou revisão. Cada cartão é uma tarefa da equipe; os materiais ficam dentro do pedido.</aside>`:`<section class="panel consult-card"><h2>${websites?'Vamos planejar seu site':'Um trabalho dedicado à sua empresa'}</h2><p>${websites?'A equipe Helpu planeja e produz seu site. Primeiro você envia o briefing;':'A equipe Helpu realiza a análise. Primeiro você envia o contexto;'} depois recebe uma proposta com entregas, valor, prazo e revisões. Enviar o formulário não gera cobrança nem análise automática.</p>${websites?'<p>Você acompanha proposta, prévia, ajustes e entrega neste espaço.</p>':'<p>Uma análise anterior pode ajudar como referência. Este serviço tem escopo e entrega próprios.</p>'}${data.canManage?btn(websites?'Solicitar meu site':'Solicitar consultoria','new','',true):'<p>Peça ao responsável pela empresa para abrir uma solicitação.</p>'}</section>`}
    <div class="assisted-toolbar"><label class="p-field"><span>Etapa</span><select data-consult-filter><option value="all">Todas as etapas</option>${Object.entries(STATES).map(([k,v])=>`<option value="${k}" ${filter===k?'selected':''}>${v}</option>`).join('')}</select></label>${admin?`<label class="p-field"><span>Empresa</span><select data-consult-client><option value="all">Todas as empresas</option>${data.clients.map(c=>`<option value="${esc(c.id)}" ${clientFilter===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label>`:''}${btn(websites?'Atualizar projetos':'Atualizar consultorias','refresh')}</div>
    <div class="consult-grid">${filtered.map(r=>`<article class="panel consult-card"><p class="overline">${esc(name(r))}</p><h2>${esc(TYPES[r.type].name)}</h2><span class="p-tag">${esc(STATES[r.state])}</span><p>${esc(next(r))}</p>${r.dueDate?`<p>Previsão: <strong>${esc(r.dueDate.split('-').reverse().join('/'))}</strong>${r.state==='paused'?' · prazo pausado':''}</p>`:''}${r.assignee?'<p class="micro-copy">Responsável: '+esc(r.assigneeName||'Equipe Helpu')+'</p>':''}${btn(r.type==='website'?'Abrir projeto':'Abrir consultoria','detail',r.id)}</article>`).join('')||'<section class="panel consult-card"><h2>Nenhuma solicitação nesta etapa</h2><p>Seus pedidos e próximos passos aparecerão aqui.</p></section>'}</div>`;
  }
  async function load(){const ticket=++sequence,company=org,mode=admin;try{const result=await api(endpoint());if(active&&ticket===sequence&&company===org&&mode===admin){data=result;paint();}}catch(e){if(active&&ticket===sequence)document.querySelector('#consult-workspace').innerHTML=`<p role="alert">${esc(e.message)}</p>${btn('Tentar novamente','refresh')}`;}}
  function briefForm(r){const type=r?.type||(websites?'website':'diagnosis'),b=r?.brief||{};openDialog(r?'Editar briefing':websites?'Solicitar site profissional':'Solicitar consultoria',form('save',r,`<p>Salve quando quiser e volte depois. Os campos com * são essenciais para enviar à equipe.</p><label class="p-field"><span>Serviço</span><select name="type">${Object.entries(TYPES).filter(([k])=>!websites||k==='website').map(([k,v])=>`<option value="${k}" ${type===k?'selected':''}>${v.name}</option>`).join('')}</select></label><p data-consult-description>${esc(TYPES[type].description)}</p><p data-consult-progress role="status"></p><div class="consult-fields">${COMMON.map(([k,v])=>area(k,v,b[k],false).replace('<span>'+esc(v)+'</span>','<span>'+esc(v)+(REQUIRED.includes(k)?' *':'')+'</span>')).join('')}</div><fieldset data-consult-branch><legend>Perguntas do serviço</legend>${TYPES[type].fields.map(([k,v])=>area(k,v+' *',b[k])).join('')}</fieldset>${chooser(files(),r?.assets)}${upload()}`,'Salvar rascunho'),true);progress(document.querySelector('[data-consult-form=save]'));}
  function progress(f){if(!f)return;const type=f.elements.type.value,fields=[...REQUIRED,...TYPES[type].fields.map(([k])=>k)];const count=fields.filter(k=>f.elements[k]?.value.trim()).length;f.querySelector('[data-consult-progress]').textContent=`Briefing: ${count} de ${fields.length} campos essenciais preenchidos.`;}
  function proposal(p){return `<section class="consult-proposal"><h3>Proposta ${p.number} · ${money(p.priceCents)}</h3><p>Prazo: ${p.businessDays} dias úteis após pagamento conferido e briefing completo. ${p.revisions} revisão(ões) consolidada(s) incluída(s), com prazo de ${p.revisionBusinessDays} dias úteis por revisão.</p><p class="micro-copy">Contagem operacional: segunda a sexta, horário de Brasília; feriados não são descontados automaticamente. Pausas por informações pendentes prorrogam a previsão. ${esc(p.deadlineRule)}</p>${[['scope','Escopo'],['deliverables','O que será entregue'],['exclusions','O que não está incluído'],['paymentInstructions','Como combinar o pagamento']].map(([k,v])=>`<h4>${v}</h4><p class="consult-text">${esc(p[k])}</p>`).join('')}<p class="micro-copy">Esta tela registra a proposta. A Helpu não inicia uma cobrança por este botão.</p></section>`;}
  function report(d,r){return `<section class="consult-report"><p class="overline">ENTREGA ${d.number} · ${esc(date(d.at))}</p>${reportFields(r).filter(([k])=>d.report[k]).map(([k,v])=>`<details ${k==='summary'?'open':''}><summary>${v}</summary><p class="consult-text">${consultationText(d.report[k],esc)}</p></details>`).join('')}${links(d.assets)}</section>`;}
  function detail(r){let actions='';if(admin){if(!['completed','canceled'].includes(r.state))actions+=btn('Assumir atendimento','assign',r.id);if(['triage','needs_info','accepted'].includes(r.state))actions+=btn('Solicitar informações','request_info',r.id);if(['triage','proposed'].includes(r.state))actions+=btn('Preparar proposta','propose',r.id,true);if(r.state==='accepted'){if(!r.payment)actions+=btn('Conferir pagamento','payment',r.id);if(!r.briefVerified)actions+=btn('Confirmar briefing completo','brief_complete',r.id);if(r.payment&&r.briefVerified)actions+=btn(r.type==='website'?'Iniciar projeto':'Iniciar consultoria','start',r.id,true);}if(r.type==='website'&&['working','revision','delivered'].includes(r.state)&&!r.finalPayment)actions+=btn('Conferir saldo final do site','settle_website',r.id);if(['working','revision'].includes(r.state))actions+=btn('Preparar entrega','deliver',r.id,true)+btn('Pausar por informação pendente','pause',r.id);if(r.state==='paused')actions+=btn('Retomar prazo','resume',r.id);}
    else if(data.canManage){if(['draft','triage','needs_info'].includes(r.state)&&!r.acceptance)actions+=btn('Editar briefing','edit',r.id);if(['draft','triage'].includes(r.state)&&!r.acceptance)actions+=btn('Enviar para análise','submit',r.id,true);if(['needs_info','paused'].includes(r.state))actions+=btn('Enviar complemento','answer',r.id,true);if(r.state==='proposed')actions+=btn('Aceitar proposta','accept_proposal',r.id,true)+btn('Pedir ajuste na proposta','decline',r.id);if(r.state==='delivered'){actions+=btn('Aceitar entrega final','complete',r.id,true);if(r.revisionsUsed<r.proposals.at(-1).revisions)actions+=btn('Solicitar revisão incluída','revise',r.id);}if(['draft','triage','needs_info','proposed'].includes(r.state)&&!r.acceptance)actions+=btn('Cancelar solicitação','cancel',r.id);}
    openDialog(TYPES[r.type].name,`<div class="consult-detail"><p class="overline">${esc(name(r))} · ${esc(STATES[r.state])}</p><p>${esc(next(r))}</p>${r.note?`<aside class="consult-notice consult-text">${esc(r.note)}</aside>`:''}${r.paused?`<p>Motivo da pausa: ${esc(r.paused.reason)}</p>`:''}${r.acceptance?`<p>Proposta ${r.acceptance.proposalNumber} aceita em ${esc(date(r.acceptance.at))}.</p><p>Pagamento: ${r.payment?'conferido manualmente pela equipe':'aguardando conferência'} · Briefing: ${r.briefVerified?'completo':'aguardando conferência'}.</p>`:''}${r.dueDate?`<p>Previsão: ${esc(r.dueDate.split('-').reverse().join('/'))} ${r.state==='paused'?'(pausada)':''}</p>`:''}${r.deliveries.length?report(r.deliveries.at(-1),r):''}${r.proposals.length?(r.deliveries.length?'<details><summary>Proposta contratada</summary>'+proposal(r.proposals.at(-1))+'</details>':proposal(r.proposals.at(-1))):''}${r.deliveries.length?`<p>Revisões utilizadas: ${r.revisionsUsed} de ${r.proposals.at(-1).revisions}. ${r.revisionsUsed>=r.proposals.at(-1).revisions?'Ajustes adicionais exigem combinar novo escopo com a equipe.':''}</p>`:''}${r.finalAcceptance?`<p>Entrega ${r.finalAcceptance.deliveryNumber} aceita em ${esc(date(r.finalAcceptance.at))}.</p>`:''}<div class="assisted-actions">${actions}</div><details><summary>Briefing e materiais enviados</summary>${[...COMMON,...TYPES[r.type].fields].filter(([k])=>r.brief[k]).map(([k,v])=>`<h4>${v}</h4><p class="consult-text">${consultationText(r.brief[k],esc)}</p>`).join('')}${links(r.assets)}${r.answers.map(a=>`<h4>Complemento · ${esc(date(a.at))}</h4><p class="consult-text">${esc(a.note)}</p>${links(a.assets)}`).join('')}</details><details><summary>Histórico e versões</summary>${r.history.map(e=>`<p>${esc(date(e.at))} · ${e.role==='operator'?'Equipe':'Cliente'} · ${esc(ACTIONS[e.action]||e.action)}${e.note?' · '+esc(e.note):''}</p>`).join('')}${r.proposals.slice(0,-1).map(proposal).join('')}${r.deliveries.slice(0,-1).map(d=>report(d,r)).join('')}</details><p class="micro-copy">Para tratar condições fora do escopo ou encerramento após contratar, fale com a equipe pelo chat do portal.</p></div>`,true);
  }
  function actionForm(action,r){let body='',title=ACTIONS[action]||'Confirmar';
    if(action==='propose'){const p=r.proposals.at(-1)||(r.type==='website'?WEBSITE_DRAFT:r.type==='diagnosis'?{priceCents:CONSULTING.priceCents,businessDays:5,revisions:1,scope:CONSULTING.description,deliverables:'Página privada com diagnóstico, análise de três concorrentes, posicionamento e plano de ação de 30 dias. Reunião de apresentação.'}:{});body=(r.type==='website'?'<label class="p-field">Modelo de escopo (sugestão interna)<select data-website-package><option value="">Preservar proposta atual</option><option value="landing">Página de conversão · R$ 2.900</option><option value="institutional">Institucional · R$ 4.900</option></select></label><p>Valores sugeridos para revisão da equipe. Ajuste o escopo antes de enviar.</p>':'')+area('scope','Escopo delimitado',p.scope,true)+area('deliverables','Entregas e formato',p.deliverables,true)+area('exclusions','Exclusões e condições fora do escopo',p.exclusions||'Não inclui gestão contínua, filmagem, novo site, registro de marca ou pesquisa primária, salvo contratação expressa.',true)+input('price','Valor total (R$)',p.priceCents?p.priceCents/100:'','number','min="0.01" step="0.01"')+input('businessDays','Prazo inicial em dias úteis',p.businessDays||'','number','min="1" max="180" step="1"')+input('revisions','Quantidade de revisões incluídas',p.revisions??1,'number','min="0" max="10" step="1"')+input('revisionBusinessDays','Prazo de cada revisão em dias úteis',p.revisionBusinessDays||'','number','min="1" max="90" step="1"')+area('deadlineRule','Condições de prazo, feriados e prazo das revisões',p.deadlineRule,true)+area('paymentInstructions','Orientações de pagamento a combinar com o cliente',p.paymentInstructions,true)+'<p>O cliente precisará aceitar esta versão antes da contratação. Não há cobrança automática.</p>';}
    else if(action==='deliver'){const d=r.reportDraft||r.deliveries.at(-1);body=(r.type==='website'?'<p>Entregue a prévia privada com checklist de testes. Confirme o saldo final antes de publicar no domínio e encerrar o projeto.</p>':'<p>Prepare uma entrega verificável. Cite fontes e datas, diferencie fatos de hipóteses e justifique prioridades. Não prometa resultados garantidos.</p>')+reportFields(r).map(([k,v])=>area(k,v,d?.report[k],['summary','evidence','facts','hypotheses','priorities','roadmap'].includes(k))).join('')+chooser(r.deliveryAssets||[],d?.assets||[])+upload(true)+'<button class="p-button secondary" type="submit" name="intent" value="report_draft" formnovalidate>Salvar rascunho da entrega</button>';title='Publicar entrega privada';}
    else if(action==='submit')body=check('consent','Autorizo a equipe Helpu a analisar o briefing e os materiais para preparar uma proposta. Entendo que ainda não há contratação ou cobrança.');
    else if(action==='accept_proposal')body=proposal(r.proposals.at(-1))+check('consent','Li e aceito esta versão do escopo, valor total, entregas, exclusões, prazo, pagamento e revisões.');
    else if(action==='complete')body=`<p>Você está aprovando a entrega ${r.deliveries.at(-1).number}.</p>`+check('consent','Revisei os materiais e aceito esta entrega final.');
    else if(action==='settle_website')body=area('note','Referência da conferência do saldo final (Pix ou boleto)','',true)+check('confirmed','Conferi o recebimento do saldo integral da proposta aceita.');
    else if(action==='payment')body='<p>Confira o recebimento real antes de registrar. Um comprovante enviado pelo cliente não confirma o pagamento por si só.</p>'+area('note','Referência da conferência (sem dados sensíveis)','',true)+check('confirmed',r.type==='website'?'Conferi a entrada acordada na proposta aceita, por Pix ou boleto.':'Conferi o recebimento integral do valor da proposta aceita, por Pix ou boleto.');
    else if(action==='brief_complete')body=check('confirmed','Revisei o briefing e confirmei que recebi as informações necessárias ao escopo contratado.');
    else if(action==='resume')body=check('confirmed','Recebi as informações pendentes e posso retomar o trabalho e o prazo.');
    else if(['request_info','pause','decline','revise','answer'].includes(action))body=area('note',{request_info:'Quais informações faltam?',pause:'Motivo da pausa e informação necessária',decline:'O que deseja mudar na proposta?',revise:'Consolide os ajustes dentro do escopo contratado',answer:'Complemento para a equipe'}[action],'',true)+(action==='answer'?chooser(files())+upload():'');
    else if(action==='start')body='<p>Iniciar registra o responsável, a data de início e a previsão conforme a proposta aceita. Pagamento e briefing precisam estar conferidos.</p>';
    else if(action==='cancel')body='<p>Cancelar encerra esta solicitação antes da contratação.</p>';
    else body='<p>Seu acesso será registrado como responsável pelo atendimento.</p>';
    openDialog(title,form(action,r,body,action==='deliver'?'Publicar entrega para revisão':'Confirmar'),true);
  }
  document.addEventListener('click',e=>{const b=e.target.closest('[data-consult]');if(!active||!b||pending)return;const a=b.dataset.consult,r=requests().find(x=>x.id===b.dataset.id);if(a==='refresh')load();else if(a==='new')briefForm();else if(r){if(a==='detail')detail(r);else if(a==='edit')briefForm(r);else actionForm(a,r);}});
  document.addEventListener('input',e=>{const f=e.target.closest('[data-consult-form=save]');if(active&&f)progress(f);});
  document.addEventListener('change',async e=>{
    if(!active)return;const el=e.target;if(el.matches('[data-consult-filter]')){filter=el.value;paint();return;}if(el.matches('[data-consult-client]')){clientFilter=el.value;paint();return;}
    const f=el.closest('[data-consult-form]');if(!f)return;
    if(el.name==='type'){f._branchValues={...(f._branchValues||{}),...Object.fromEntries(new FormData(f))};f.querySelector('[data-consult-branch]').innerHTML='<legend>Perguntas do serviço</legend>'+TYPES[el.value].fields.map(([k,v])=>area(k,v+' *',f._branchValues[k]||'')).join('');f.querySelector('[data-consult-description]').textContent=TYPES[el.value].description;progress(f);return;}
    if(!el.matches('[data-consult-upload]')||!el.files[0]||pending)return;const file=el.files[0],mode=admin,company=org;pending=true;f.querySelector('button:not([type])').disabled=true;const err=f.querySelector('[role=alert]');err.hidden=true;
    try{let a;if(el.dataset.consultUpload==='delivery'){if(file.size>3*1024*1024)throw new Error('Envie anexos de entrega de até 3 MB.');const response=await fetch('/api/portal/consultations-admin/files',{method:'POST',credentials:'same-origin',headers:{'Content-Type':file.type,'X-Company-Id':f.dataset.org,'X-Consultation-Id':f.dataset.id,'X-Record-Version':f.dataset.version,'X-File-Name':encodeURIComponent(file.name)},body:file});const result=await response.json();if(!response.ok)throw new Error(result.error||'Não foi possível anexar.');f.dataset.version=result.version;if(active&&mode===admin&&company===org&&data){const i=data.requests.findIndex(x=>x.id===result.id);if(i>=0)data.requests[i]=result;}a=result.deliveryAssets.at(-1);}else{a=await uploadFile('/api/portal/'+company+'/files',file);if(active&&mode===admin&&company===org)extraAssets.push(a);}if(active&&mode===admin&&company===org&&f.isConnected){f.querySelector('[data-consult-assets]').insertAdjacentHTML('beforeend',`<label class="assisted-check"><input type="checkbox" name="assetIds" value="${esc(a.id)}" checked><span>${esc(a.name)}</span></label>`);toast('Arquivo anexado. Salve ou envie o formulário para concluir.');}}
    catch(error){err.textContent=error.message;err.hidden=false;}finally{pending=false;el.value='';f.querySelector('button:not([type])').disabled=false;}
  });
  document.addEventListener('change',e=>{if(!active||!e.target.matches('[data-website-package]'))return;const choice=WEBSITE_PACKAGES[e.target.value],f=e.target.closest('form');if(!choice||!f)return;for(const [key,value]of Object.entries(choice)){const field=f.elements[key==='priceCents'?'price':key];if(field)field.value=key==='priceCents'?value/100:value;}});
  document.addEventListener('submit',async e=>{const f=e.target.closest('[data-consult-form]');if(!active||!f)return;e.preventDefault();if(pending)return;const values=new FormData(f),action=e.submitter?.value==='report_draft'?'report_draft':f.dataset.consultForm,input={...Object.fromEntries(values),id:f.dataset.id||undefined,orgId:f.dataset.org,version:Number(f.dataset.version),requestKey:f.dataset.key,action,consent:values.get('consent')==='on',confirmed:values.get('confirmed')==='on',assetIds:values.getAll('assetIds')};
    if(action==='save')input.brief=Object.fromEntries(values);if(action==='propose'){input.priceCents=Math.round(Number(input.price)*100);input.businessDays=Number(input.businessDays);input.revisions=Number(input.revisions);input.revisionBusinessDays=Number(input.revisionBusinessDays);}if(['report_draft','deliver'].includes(action))input.report=Object.fromEntries(values);
    const company=org,mode=admin,url=endpoint();pending=true;const button=f.querySelector('button:not([type])');button.disabled=true;
    try{const result=await api(url,'POST',input);if(active&&company===org&&mode===admin){closeDialog();await load();toast(action==='save'?'Rascunho salvo. Confira e envie para análise quando estiver pronto.':'Alteração registrada.');if(action==='save')detail(result);}}
    catch(error){const err=f.querySelector('[role=alert]');err.textContent=error.message;err.hidden=false;}finally{pending=false;button.disabled=false;}
  });
  return {websitePage(){return websiteShowcase()+'<div id="consult-workspace"></div>';},page(mode=false){return `<section class="page-heading"><div><p class="overline">${mode?'OPERAÇÃO HELPU':'CONSULTORIAS'}</p><h1>${mode?'Consultorias da equipe':'Direção para o próximo passo.'}</h1><p>${mode?'Analise os pedidos, prepare propostas e conduza cada entrega.':'Diagnóstico, mercado, identidade e presença com acompanhamento humano.'}</p></div></section><div id="consult-workspace"></div>`;},mount(view){const next=['consultations','consultations-admin','websites'].includes(view);if(!next){active=false;++sequence;return;}websites=view==='websites';const mode=view==='consultations-admin',company=getState()?.company.id||'';if(company!==org||mode!==admin){extraAssets=[];filter='all';clientFilter='all';}org=company;admin=mode;active=true;data=null;if(admin&&!getBoot()?.operator){document.querySelector('#consult-workspace').innerHTML='<p>Acesso restrito à equipe autorizada.</p>';return;}paint();load();}};
}
